# Generated by build.py from recipe.yml for recipe ftp-see-which-command-broke-a-transfer. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/outbox', 'site/inbox', 'plain/outbox' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'nightly.csv'), "id,total`n1,42`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/outbox/README.txt'), "Uploads land here.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/inbox/orders.csv'), "order,qty`n7,3`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/outbox/README.txt'), "Uploads land here.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'job.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# job.sh FTP-URL: the FTP job. It uploads nightly.csv to outbox/ under the URL (ending in /), then fetches`n# inbox/orders.csv. A failed step is curl's exit code, and the job stops there.`ncurl -sS -T nightly.csv `"`${1}outbox/nightly.csv`" || exit`ncurl -sS -o orders.csv `"`${1}inbox/orders.csv`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'settled.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# settled.sh LOG: waits until every exchange surl's log says was opened has ended, so the log holds the whole`n# of each one. It gives up after 5 seconds, leaving the log as it is.`ntries=0`nwhile [ `"`$(grep -c ' opened: ' `"`$1`")`" -gt `"`$(grep -c ' ended; ' `"`$1`")`" ] && [ `"`$tries`" -lt 25 ]; do`n  sleep 0.2`n  tries=`$((tries + 1))`ndone`n")
[IO.File]::WriteAllText((Join-Path $PWD 'failed-sessions.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# failed-sessions.sh LOG: reads surl's verbose log and prints each session (exchange) that ended on a failure:`n# the last command the client sent before it quit or the connection closed, and the reply that ended it, a 4xx`n# or 5xx, or `"no reply`". A line surl logged about that command follows, if there is one. Bytes on a data`n# connection are not commands and are skipped. Exit 1 when no session failed.`ntr -d '\r' < `"`$1`" | awk '`n  { n = substr(`$1, 2); text = substr(`$0, length(`$1) + 4); sub(/\\r\\n`$/, `"`", text) }`n  `$2 == `"*`" && `$3 == `"Data`" && `$5 == `"opened:`" { data[n] = 1; next }`n  `$2 == `"*`" && `$3 == `"Data`" && `$5 == `"closed.`" { data[n] = 0; next }`n  `$2 == `"*`" && `$3 == `"Exchange`" && `$5 == `"ended;`" {`n    if (cmd[n] != `"`" && (reply[n] == `"`" || reply[n] ~ /^[45]/)) {`n      print `"exchange `" n `": `" cmd[n] `" -> `" (reply[n] == `"`" ? `"no reply`" : reply[n])`n      if (note[n] != `"`") print `"  surl: `" note[n]`n      failed = 1`n    }`n    next`n  }`n  quit[n] { next }`n  `$2 == `"*`" && cmd[n] != `"`" && note[n] == `"`" { note[n] = text; next }`n  `$2 == `"<`" && !data[n] {`n    if (text == `"QUIT`") { quit[n] = 1 } else { cmd[n] = text; reply[n] = `"`"; note[n] = `"`" }`n    next`n  }`n  `$2 == `">`" && cmd[n] != `"`" && `$3 ~ /^[1-5][0-9][0-9]`$/ { reply[n] = text }`n  END { if (!failed) { print `"no failed session in the log`"; exit 1 } }'`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'job.log', '--allow-anonymous', '--allow-uploads', '--fault', '"error;scheme=ftp;command=STOR;path=/outbox;reply=451', 'Local', 'error', 'in', 'processing;times=1"', '--fault', '"drop;stage=command;command=RETR;path=/inbox;times=1"', '--directory', 'site', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList '-v', '--log-file', 'plain.log', '--allow-anonymous', '--directory', 'plain', 'ftp://127.0.0.1:8081/' -PassThru -NoNewWindow
$server2 = Start-Process surl -ArgumentList '--allow-uploads', 'ftp://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh settled.sh job.log && sh failed-sessions.sh job.log } finally { Stop-Process $server0; Stop-Process $server1; Stop-Process $server2 }
